#!/usr/bin/env python3
"""
Lightweight JSON Schema validator for AI agent messages.
Zero external dependencies – uses Python's built-in json module.
"""

import json
import uuid
from datetime import datetime
from typing import Dict, Any, Optional, List


class AgentMessageValidator:
    """Validator for AI agent messages using JSON Schema."""

    def __init__(self, schema_path: Optional[str] = None):
        """
        Initialize validator.

        Args:
            schema_path: Optional path to schema file. If None, uses default.
        """
        if schema_path:
            with open(schema_path, 'r') as f:
                self.schema = json.load(f)
        else:
            # Default schema for agent messages
            self.schema = {
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "type": "object",
                "required": ["message_id", "timestamp", "sender", "content", "type"],
                "properties": {
                    "message_id": {"type": "string", "format": "uuid"},
                    "timestamp": {"type": "string", "format": "date-time"},
                    "sender": {"type": "string", "pattern": "^[^@]+@[^@]+\\.[^@]+$"},
                    "recipients": {
                        "type": "array",
                        "items": {"type": "string", "pattern": "^[^@]+@[^@]+\\.[^@]+$"}
                    },
                    "content": {"type": "object"},
                    "type": {
                        "type": "string",
                        "enum": ["query", "response", "notification", "error", "coordination"]
                    },
                    "metadata": {"type": "object"},
                    "references": {"type": "array", "items": {"type": "string"}}
                }
            }

    def validate(self, message: Dict[str, Any]) -> List[str]:
        """
        Validate an agent message against the schema.

        Returns:
            List of validation errors (empty list if valid).
        """
        errors = []

        # Check required fields
        for field in self.schema.get("required", []):
            if field not in message:
                errors.append(f"Missing required field: '{field}'")

        # Validate field types and formats
        for field, value in message.items():
            if field in self.schema.get("properties", {}):
                prop_schema = self.schema["properties"][field]
                errors.extend(self._validate_field(field, value, prop_schema))

        return errors

    def _validate_field(self, field: str, value: Any, schema: Dict[str, Any]) -> List[str]:
        """Validate a single field against its schema."""
        errors = []

        # Type validation
        if "type" in schema:
            expected_type = schema["type"]
            if expected_type == "string" and not isinstance(value, str):
                errors.append(f"Field '{field}' must be a string")
            elif expected_type == "array" and not isinstance(value, list):
                errors.append(f"Field '{field}' must be an array")
            elif expected_type == "object" and not isinstance(value, dict):
                errors.append(f"Field '{field}' must be an object")

        # Format validation
        if isinstance(value, str) and "format" in schema:
            if schema["format"] == "uuid":
                try:
                    uuid.UUID(value)
                except ValueError:
                    errors.append(f"Field '{field}' must be a valid UUID")
            elif schema["format"] == "date-time":
                try:
                    datetime.fromisoformat(value.replace('Z', '+00:00'))
                except ValueError:
                    errors.append(f"Field '{field}' must be a valid ISO 8601 datetime")

        # Pattern validation
        if isinstance(value, str) and "pattern" in schema:
            import re
            if not re.match(schema["pattern"], value):
                errors.append(f"Field '{field}' does not match required pattern")

        # Enum validation
        if "enum" in schema and value not in schema["enum"]:
            errors.append(f"Field '{field}' must be one of: {schema['enum']}")

        # Array item validation
        if isinstance(value, list) and "items" in schema:
            for i, item in enumerate(value):
                errors.extend(self._validate_field(f"{field}[{i}]", item, schema["items"]))

        return errors

    def validate_json_string(self, json_str: str) -> List[str]:
        """
        Validate a JSON string directly.

        Returns:
            List of validation errors (empty list if valid).
        """
        try:
            message = json.loads(json_str)
            return self.validate(message)
        except json.JSONDecodeError as e:
            return [f"Invalid JSON: {str(e)}"]


# Quick usage example
if __name__ == "__main__":
    validator = AgentMessageValidator()

    # Example valid message
    valid_message = {
        "message_id": "123e4567-e89b-12d3-a456-426614174000",
        "timestamp": "2024-08-24T11:20:00Z",
        "sender": "agent1@example.org",
        "recipients": ["agent2@example.org"],
        "content": {"text": "Hello world"},
        "type": "query"
    }

    errors = validator.validate(valid_message)
    if errors:
        print("Validation errors:", errors)
    else:
        print("Message is valid!")
```

