```typescript
/**
 * Lightweight JSON Schema validator for AI agent messages.
 * Zero external dependencies – uses native JSON.parse and basic [REDACTED]
 */

interface AgentMessage {
  message_id: string;
  timestamp: string;
  sender: string;
  content: Record<string, any>;
  type: 'query' | 'response' | 'notification' | 'error' | 'coordination';
  recipients?: string[];
  metadata?: Record<string, any>;
  references?: string[];
}

interface ValidationResult {
  valid: boolean;
  errors: string[];
}

class AgentMessageValidator {
  private defaultSchema = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    type: 'object' as const,
    required: ['message_id', 'timestamp', 'sender', 'content', 'type'] as const,
    properties: {
      message_id: { type: 'string', format: 'uuid' },
      timestamp: { type: 'string', format: 'date-time' },
      sender: { type: 'string', pattern: '^[^@]+@[^@]+\\.[^@]+$' },
      recipients: {
        type: 'array',
        items: { type: 'string', pattern: '^[^@]+@[^@]+\\.[^@]+$' }
      },
      content: { type: 'object' },
      type: {
        type: 'string',
        enum: ['query', 'response', 'notification', 'error', 'coordination']
      },
      metadata: { type: 'object' },
      references: { type: 'array', items: { type: 'string' } }
    }
  };

  validate(message: any): ValidationResult {
    const errors: string[] = [];

    // Check required fields
    for (const field of this.defaultSchema.required) {
      if (!(field in message)) {
        errors.push(`Missing required field: '${field}'`);
      }
    }

    // Validate each field
    for (const [field, value] of Object.entries(message)) {
      const schema = (this.defaultSchema.properties as any)[field];
      if (schema) {
        errors.push(...this.validateField(field, value, schema));
      }
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }

  validateJSON(jsonString: string): ValidationResult {
    try {
      const message = JSON.parse(jsonString);
      return this.validate(message);
    } catch (error) {
      return {
        valid: false,
        errors: [`Invalid JSON: ${error.message}`]
      };
    }
  }

  private validateField(field: string, value: any, schema: any): string[] {
    const errors: string[] = [];

    // Type validation
    if (schema.type === 'string' && typeof value !== 'string') {
      errors.push(`Field '${field}' must be a string`);
    } else if (schema.type === 'array' && !Array.isArray(value)) {
      errors.push(`Field '${field}' must be an array`);
    } else if (schema.type === 'object' && (typeof value !== 'object' || Array.isArray(value))) {
      errors.push(`Field '${field}' must be an object`);
    }

    // Format validation
    if (typeof value === 'string' && schema.format) {
      if (schema.format === 'uuid' && !this.isValidUUID(value)) {
        errors.push(`Field '${field}' must be a valid UUID`);
      } else if (schema.format === 'date-time' && !this.isValidDateTime(value)) {
        errors.push(`Field '${field}' must be a valid ISO 8601 datetime`);
      }
    }

    // Pattern validation
    if (typeof value === 'string' && schema.pattern) {
      const regex = new RegExp(schema.pattern);
      if (!regex.test(value)) {
        errors.push(`Field '${field}' does not match required pattern`);
      }
    }

    // Enum validation
    if (schema.enum && !schema.enum.includes(value)) {
      errors.push(`Field '${field}' must be one of: ${schema.enum.join(', ')}`);
    }

    // Array item validation
    if (Array.isArray(value) && schema.items) {
      for (let i = 0; i < value.length; i++) {
        errors.push(...this.validateField(`${field}[${i}]`, value[i], schema.items));
      }
    }

    return errors;
  }

  private isValidUUID(str: string): boolean {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(str);
  }

  private isValidDateTime(str: string): boolean {
    try {
      const date = new Date(str);
      return !isNaN(date.getTime()) && str.includes('T');
    } catch {
      return false;
    }
  }
}

// Export for both Node.js and browser
export { AgentMessageValidator, type AgentMessage, type ValidationResult };

// Simple usage example
if (typeof window !== 'undefined') {
  // Browser usage
  (window as any).AgentMessageValidator = AgentMessageValidator;
} else if (typeof module !== 'undefined') {
  // Node.js usage
  module.exports = { AgentMessageValidator, AgentMessage, ValidationResult };
}
